"""SQLAlchemy 2.x models aligned to approved InCIT Schema v1.0.
Published schedule immutability is enforced by the service layer and SQLite triggers
in the migration; validators are intentionally solver-independent.
"""
from __future__ import annotations
from datetime import datetime, date, time
from sqlalchemy import (String, Integer, Boolean, Date, DateTime, Time, ForeignKey,
    UniqueConstraint, CheckConstraint, Index, Text, JSON, func)
from sqlalchemy.orm import Mapped, mapped_column, relationship
from .db import Base

# IDs are string UUIDs generated by the application; this keeps SQLite and API IDs portable.
def id_col(): return mapped_column(String(36), primary_key=True)
def created_col(): return mapped_column(DateTime, nullable=False, server_default=func.current_timestamp())

class User(Base):
    __tablename__="users"
    id=id_col(); full_name:Mapped[str]=mapped_column(String(160),nullable=False)
    email:Mapped[str]=mapped_column(String(254),nullable=False,unique=True,index=True)
    password_hash:Mapped[str]=mapped_column(String(255),nullable=False)
    is_active:Mapped[bool]=mapped_column(Boolean,nullable=False,default=True)
    created_at=created_col(); updated_at:Mapped[datetime]=mapped_column(DateTime,nullable=False,server_default=func.current_timestamp(),onupdate=func.current_timestamp())

class Role(Base):
    __tablename__="roles"
    id=id_col(); name:Mapped[str]=mapped_column(String(40),nullable=False,unique=True); description:Mapped[str|None]=mapped_column(Text)

class UserRole(Base):
    __tablename__="user_roles"
    user_id:Mapped[str]=mapped_column(ForeignKey("users.id",ondelete="CASCADE"),primary_key=True)
    role_id:Mapped[str]=mapped_column(ForeignKey("roles.id",ondelete="CASCADE"),primary_key=True)
    assigned_at=created_col(); assigned_by:Mapped[str|None]=mapped_column(ForeignKey("users.id"))

class Department(Base):
    __tablename__="departments"
    id=id_col(); code:Mapped[str]=mapped_column(String(20),nullable=False,unique=True); name:Mapped[str]=mapped_column(String(120),nullable=False); is_active:Mapped[bool]=mapped_column(Boolean,nullable=False,default=True)

class AcademicTerm(Base):
    __tablename__="academic_terms"
    id=id_col(); name:Mapped[str]=mapped_column(String(100),nullable=False); start_date:Mapped[date]=mapped_column(Date,nullable=False); end_date:Mapped[date]=mapped_column(Date,nullable=False); status:Mapped[str]=mapped_column(String(20),nullable=False,default="planned")
    __table_args__=(CheckConstraint("start_date < end_date",name="ck_term_dates"),CheckConstraint("status IN ('planned','active','completed')",name="ck_term_status"))

class Faculty(Base):
    __tablename__="faculty"
    id=id_col(); user_id:Mapped[str]=mapped_column(ForeignKey("users.id"),nullable=False,unique=True); department_id:Mapped[str]=mapped_column(ForeignKey("departments.id"),nullable=False); faculty_code:Mapped[str]=mapped_column(String(30),nullable=False,unique=True); designation:Mapped[str|None]=mapped_column(String(80)); max_daily_hours:Mapped[int|None]=mapped_column(Integer); max_weekly_hours:Mapped[int|None]=mapped_column(Integer); is_active:Mapped[bool]=mapped_column(Boolean,nullable=False,default=True)
    __table_args__=(CheckConstraint("max_daily_hours IS NULL OR max_daily_hours >= 0"),CheckConstraint("max_weekly_hours IS NULL OR max_weekly_hours >= 0"))

class StudentGroup(Base):
    __tablename__="student_groups"
    id=id_col(); department_id:Mapped[str]=mapped_column(ForeignKey("departments.id"),nullable=False); name:Mapped[str]=mapped_column(String(80),nullable=False); academic_year:Mapped[int]=mapped_column(Integer,nullable=False); semester:Mapped[int]=mapped_column(Integer,nullable=False); section:Mapped[str|None]=mapped_column(String(20)); student_count:Mapped[int]=mapped_column(Integer,nullable=False); is_active:Mapped[bool]=mapped_column(Boolean,nullable=False,default=True)
    __table_args__=(CheckConstraint("student_count >= 1"),UniqueConstraint("department_id","academic_year","semester","name","section",name="uq_group_identity"))

class Course(Base):
    __tablename__="courses"
    id=id_col(); department_id:Mapped[str]=mapped_column(ForeignKey("departments.id"),nullable=False); code:Mapped[str]=mapped_column(String(30),nullable=False,unique=True); name:Mapped[str]=mapped_column(String(160),nullable=False); course_type:Mapped[str]=mapped_column(String(20),nullable=False); credits:Mapped[int]=mapped_column(Integer,nullable=False,default=0); is_active:Mapped[bool]=mapped_column(Boolean,nullable=False,default=True)
    __table_args__=(CheckConstraint("course_type IN ('lecture','lab','tutorial','seminar')"),CheckConstraint("credits >= 0"))

class CourseOffering(Base):
    __tablename__="course_offerings"
    id=id_col(); course_id:Mapped[str]=mapped_column(ForeignKey("courses.id"),nullable=False); faculty_id:Mapped[str]=mapped_column(ForeignKey("faculty.id"),nullable=False); student_group_id:Mapped[str]=mapped_column(ForeignKey("student_groups.id"),nullable=False); academic_term_id:Mapped[str]=mapped_column(ForeignKey("academic_terms.id"),nullable=False); required_sessions_per_week:Mapped[int]=mapped_column(Integer,nullable=False); session_duration_minutes:Mapped[int]=mapped_column(Integer,nullable=False); preferred_room_type:Mapped[str|None]=mapped_column(String(30)); is_active:Mapped[bool]=mapped_column(Boolean,nullable=False,default=True)
    __table_args__=(UniqueConstraint("course_id","faculty_id","student_group_id","academic_term_id",name="uq_offering_term"),CheckConstraint("required_sessions_per_week >= 1"),CheckConstraint("session_duration_minutes > 0"))

class CourseRequirement(Base):
    __tablename__="course_requirements"
    id=id_col(); course_offering_id:Mapped[str]=mapped_column(ForeignKey("course_offerings.id",ondelete="CASCADE"),nullable=False,index=True); requirement_type:Mapped[str]=mapped_column(String(30),nullable=False); value:Mapped[dict]=mapped_column(JSON,nullable=False); is_hard_constraint:Mapped[bool]=mapped_column(Boolean,nullable=False,default=True)

class Building(Base):
    __tablename__="buildings"
    id=id_col(); code:Mapped[str]=mapped_column(String(20),nullable=False,unique=True); name:Mapped[str]=mapped_column(String(120),nullable=False); location_description:Mapped[str|None]=mapped_column(Text)

class Room(Base):
    __tablename__="rooms"
    id=id_col(); building_id:Mapped[str]=mapped_column(ForeignKey("buildings.id"),nullable=False); code:Mapped[str]=mapped_column(String(30),nullable=False); name:Mapped[str]=mapped_column(String(100),nullable=False); room_type:Mapped[str]=mapped_column(String(30),nullable=False); capacity:Mapped[int]=mapped_column(Integer,nullable=False); is_accessible:Mapped[bool]=mapped_column(Boolean,nullable=False,default=False); is_active:Mapped[bool]=mapped_column(Boolean,nullable=False,default=True)
    __table_args__=(UniqueConstraint("building_id","code",name="uq_room_building_code"),CheckConstraint("capacity >= 1"),Index("ix_rooms_active_type_capacity","is_active","room_type","capacity"))

class Resource(Base):
    __tablename__="resources"
    id=id_col(); code:Mapped[str]=mapped_column(String(30),nullable=False,unique=True); name:Mapped[str]=mapped_column(String(120),nullable=False); category:Mapped[str]=mapped_column(String(50),nullable=False); total_quantity:Mapped[int]=mapped_column(Integer,nullable=False); is_independently_bookable:Mapped[bool]=mapped_column(Boolean,nullable=False,default=False); is_active:Mapped[bool]=mapped_column(Boolean,nullable=False,default=True)
    __table_args__=(CheckConstraint("total_quantity >= 0"),)

class RoomResource(Base):
    __tablename__="room_resources"
    room_id:Mapped[str]=mapped_column(ForeignKey("rooms.id",ondelete="CASCADE"),primary_key=True); resource_id:Mapped[str]=mapped_column(ForeignKey("resources.id",ondelete="CASCADE"),primary_key=True); quantity:Mapped[int]=mapped_column(Integer,nullable=False,default=1)
    __table_args__=(CheckConstraint("quantity >= 0"),)

class ResourceRequirement(Base):
    __tablename__="resource_requirements"
    id=id_col(); course_offering_id:Mapped[str]=mapped_column(ForeignKey("course_offerings.id",ondelete="CASCADE"),nullable=False); resource_id:Mapped[str]=mapped_column(ForeignKey("resources.id"),nullable=False); quantity_required:Mapped[int]=mapped_column(Integer,nullable=False); is_hard_constraint:Mapped[bool]=mapped_column(Boolean,nullable=False,default=True)
    __table_args__=(UniqueConstraint("course_offering_id","resource_id",name="uq_offering_resource_req"),CheckConstraint("quantity_required >= 1"))

class TimeSlot(Base):
    __tablename__="time_slots"
    id=id_col(); day_of_week:Mapped[int]=mapped_column(Integer,nullable=False); start_time:Mapped[time]=mapped_column(Time,nullable=False); end_time:Mapped[time]=mapped_column(Time,nullable=False); label:Mapped[str]=mapped_column(String(50),nullable=False)
    __table_args__=(CheckConstraint("day_of_week BETWEEN 0 AND 6"),CheckConstraint("start_time < end_time"),Index("ix_timeslot_day_start","day_of_week","start_time"))

class FacultyAvailability(Base):
    __tablename__="faculty_availability"
    id=id_col(); faculty_id:Mapped[str]=mapped_column(ForeignKey("faculty.id",ondelete="CASCADE"),nullable=False); day_of_week:Mapped[int]=mapped_column(Integer,nullable=False); start_time:Mapped[time]=mapped_column(Time,nullable=False); end_time:Mapped[time]=mapped_column(Time,nullable=False); availability_type:Mapped[str]=mapped_column(String(20),nullable=False); effective_from:Mapped[date|None]=mapped_column(Date); effective_until:Mapped[date|None]=mapped_column(Date)
    __table_args__=(CheckConstraint("day_of_week BETWEEN 0 AND 6"),CheckConstraint("start_time < end_time"),CheckConstraint("availability_type IN ('available','unavailable')"),Index("ix_faculty_availability_lookup","faculty_id","day_of_week"))

class Schedule(Base):
    __tablename__="schedules"
    id=id_col(); academic_term_id:Mapped[str]=mapped_column(ForeignKey("academic_terms.id"),nullable=False); name:Mapped[str]=mapped_column(String(120),nullable=False); version_number:Mapped[int]=mapped_column(Integer,nullable=False); parent_schedule_id:Mapped[str|None]=mapped_column(ForeignKey("schedules.id")); status:Mapped[str]=mapped_column(String(20),nullable=False,default="draft"); created_by:Mapped[str]=mapped_column(ForeignKey("users.id"),nullable=False); created_at=created_col(); published_at:Mapped[datetime|None]=mapped_column(DateTime); solver_status:Mapped[str]=mapped_column(String(20),nullable=False,default="not_run")
    __table_args__=(UniqueConstraint("academic_term_id","version_number",name="uq_schedule_term_version"),CheckConstraint("version_number >= 1"),CheckConstraint("status IN ('draft','published','archived')"),CheckConstraint("solver_status IN ('not_run','feasible','optimal','infeasible','unknown')"),Index("ix_schedule_term_status","academic_term_id","status"))

class TimetableEntry(Base):
    __tablename__="timetable_entries"
    id=id_col(); schedule_id:Mapped[str]=mapped_column(ForeignKey("schedules.id",ondelete="RESTRICT"),nullable=False); course_offering_id:Mapped[str]=mapped_column(ForeignKey("course_offerings.id"),nullable=False); room_id:Mapped[str]=mapped_column(ForeignKey("rooms.id"),nullable=False); start_datetime:Mapped[datetime]=mapped_column(DateTime,nullable=False); end_datetime:Mapped[datetime]=mapped_column(DateTime,nullable=False); status:Mapped[str]=mapped_column(String(20),nullable=False,default="scheduled"); source:Mapped[str]=mapped_column(String(20),nullable=False,default="solver"); created_at=created_col()
    __table_args__=(CheckConstraint("start_datetime < end_datetime"),CheckConstraint("status IN ('scheduled','cancelled')"),CheckConstraint("source IN ('solver','manual','rescheduled')"),Index("ix_entry_schedule_time","schedule_id","start_datetime","end_datetime"),Index("ix_entry_room_time","room_id","start_datetime","end_datetime"))

class SchedulePublication(Base):
    __tablename__="schedule_publications"
    id=id_col(); schedule_id:Mapped[str]=mapped_column(ForeignKey("schedules.id",ondelete="RESTRICT"),nullable=False,unique=True); published_by:Mapped[str]=mapped_column(ForeignKey("users.id"),nullable=False); published_at:Mapped[datetime]=mapped_column(DateTime,nullable=False,server_default=func.current_timestamp()); publication_note:Mapped[str|None]=mapped_column(Text)

class SpecialWeek(Base):
    __tablename__="special_weeks"
    id=id_col(); academic_term_id:Mapped[str]=mapped_column(ForeignKey("academic_terms.id"),nullable=False); name:Mapped[str]=mapped_column(String(120),nullable=False); start_date:Mapped[date]=mapped_column(Date,nullable=False); end_date:Mapped[date]=mapped_column(Date,nullable=False); event_type:Mapped[str]=mapped_column(String(20),nullable=False); booking_policy:Mapped[str]=mapped_column(String(30),nullable=False,default="normal"); allow_timetable_modifications:Mapped[bool]=mapped_column(Boolean,nullable=False,default=False); status:Mapped[str]=mapped_column(String(20),nullable=False,default="planned"); created_by:Mapped[str]=mapped_column(ForeignKey("users.id"),nullable=False)
    __table_args__=(CheckConstraint("start_date <= end_date"),CheckConstraint("event_type IN ('festival','examination','holiday','other')"),CheckConstraint("booking_policy IN ('normal','restricted','approval_required','blocked')"),CheckConstraint("status IN ('planned','active','completed')"),Index("ix_special_week_dates","academic_term_id","start_date","end_date"))

class SpecialWeekOverride(Base):
    __tablename__="special_week_overrides"
    id=id_col(); special_week_id:Mapped[str]=mapped_column(ForeignKey("special_weeks.id",ondelete="CASCADE"),nullable=False); override_type:Mapped[str]=mapped_column(String(30),nullable=False); room_id:Mapped[str|None]=mapped_column(ForeignKey("rooms.id")); resource_id:Mapped[str|None]=mapped_column(ForeignKey("resources.id")); start_datetime:Mapped[datetime|None]=mapped_column(DateTime); end_datetime:Mapped[datetime|None]=mapped_column(DateTime); policy_value:Mapped[dict]=mapped_column(JSON,nullable=False,default=dict); reason:Mapped[str]=mapped_column(Text,nullable=False); created_by:Mapped[str]=mapped_column(ForeignKey("users.id"),nullable=False); created_at=created_col()
