    id=id_col(); requester_id:Mapped[str]=mapped_column(ForeignKey("users.id"),nullable=False); room_id:Mapped[str]=mapped_column(ForeignKey("rooms.id"),nullable=False); special_week_id:Mapped[str|None]=mapped_column(ForeignKey("special_weeks.id")); title:Mapped[str]=mapped_column(String(160),nullable=False); purpose:Mapped[str]=mapped_column(Text,nullable=False); start_datetime:Mapped[datetime]=mapped_column(DateTime,nullable=False); end_datetime:Mapped[datetime]=mapped_column(DateTime,nullable=False); expected_attendees:Mapped[int]=mapped_column(Integer,nullable=False); status:Mapped[str]=mapped_column(String(20),nullable=False,default="pending"); approval_required:Mapped[bool]=mapped_column(Boolean,nullable=False,default=True); approved_by:Mapped[str|None]=mapped_column(ForeignKey("users.id")); approved_at:Mapped[datetime|None]=mapped_column(DateTime); created_at=created_col(); updated_at:Mapped[datetime]=mapped_column(DateTime,nullable=False,server_default=func.current_timestamp(),onupdate=func.current_timestamp())
