    id=id_col(); schedule_id:Mapped[str]=mapped_column(ForeignKey("schedules.id",ondelete="RESTRICT"),nullable=False); timetable_entry_id:Mapped[str]=mapped_column(ForeignKey("timetable_entries.id",ondelete="RESTRICT"),nullable=False); requested_by:Mapped[str]=mapped_column(ForeignKey("users.id"),nullable=False); change_type:Mapped[str]=mapped_column(String(30),nullable=False); old_values:Mapped[dict]=mapped_column(JSON,nullable=False); proposed_values:Mapped[dict]=mapped_column(JSON,nullable=False); reason:Mapped[str]=mapped_column(Text,nullable=False); status:Mapped[str]=mapped_column(String(20),nullable=False,default="pending"); created_at=created_col(); resolved_at:Mapped[datetime|None]=mapped_column(DateTime)
